INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(124, 'ruRU', 'Missing WDB data.', 0),
(339, 'ruRU', 'Между тем, я отправляю лейтенанта Алверолда в разведывательную миссию по континенту Калимдор. Его силы должны выполнить свою задачу, а затем присоединиться к нашим силам в крепости Тирагард. Предполагается, что миссия лейтенанта Алверолда продлится довольно долго. Новая земля кажется огромной и опасной. Но если со мной или Бенедиктом случится несчастье, войска Алверолда возьмут крепость обратно. Мы будем посылать волну за волной, пока этот бастион не станет нашим! --Адмирал Праудмур', 0),
(349, 'ruRU', 'Тот факт, что мы имеем дело с различными разбойничьими элементами здесь, заставляет меня думать, что нам понадобится поддержка Королевской армии. Не только раскопки потребуют военной поддержки, но, судя по моему неопытному взгляду, расположение Бейл Модана может иметь стратегическую ценность для Альянса, учитывая нестабильность мировой политики в её текущем состоянии. Увы, я отвлёкся. Под скалой предстоит ещё много работы. Я потратил слишком много времени на писанину и слишком мало на копание...', 0),
(351, 'ruRU', 'Пульт управления самофланжем можно использовать для автоматического регулирования потока топлива, газов, жидкостей и связанных механизмов. После завершения начальной настройки он должен работать без проблем при минимальном обслуживании. Краткий перечень компонентов пульта управления (слева направо) I. Главный рычаг питания В включённом положении активирует самофланж. Управляющий механизм не отключится автоматически при переводе рычага в выключенное положение. Это просто', 0),
(360, 'ruRU', 'Земля содрогнулась, когда древние деревья заколдованного леса были вырваны с корнем и повержены. Рощи и поляны, за которыми ухаживали сыновья и дочери Кенария, и каменные башни детей звёзд были сровнены с холмистой землёй. Там была наша королева, лучезарная даже в отчаянии, в хаосе, которым стали битвы. Заколдованное небо меняло цвета от выброса магии, от взрывов, грозивших разорвать мир на части. Брат сражался с братом. Избранные сражались', 0),
(363, 'ruRU', 'Мастер Делгрен, всё так, как вы и боялись. Ваша теория о Башне Алталаксса подтвердилась. У башни собрался культ, среди них много колдунов, включая даже отвратительного сатира. Они зовут себя Культом Тёмной Нити. Не могу представить, какая гнусная цель их объединяет, но это меня тревожит. Простите за краткость этого письма, но в лесу вокруг меня таится опасность, и я могу позволить себе лишь немного слов для описания ситуации. Я', 0),
(386, 'ruRU', 'Здесь следует отметить, что податель этого донесения оказал решающую роль не только в успехе нашей миссии, но и в поражении Ивара Мерзкого, спасении Эрланда и доставке этого донесения. Мы выражаем свою благодарность и рекомендуем командованию отметить этого человека наградами, достойными такого доблестного поведения, проявленного в полевых условиях. -Ловец Смерти Рейн Йорик, руководитель миссии', 0),
(393, 'ruRU', 'И так он скитался, и он искал. И рука его оставалась потерянной для него. И потому он проклинал и рычал, пока шёл. Но Гри''лек уже давно отвернул ухо от духов, и они разгневались и не стали слушать его проклятия. Гри''лек был обречён. Обречён скитаться безрукий.', 0),
(416, 'ruRU', 'Джин''Зил, прошло немало времени, но я подумал, тебе будет приятно узнать, что последние из Кровавых Перьев были убиты. Впрочем, не благодари меня — тот, кто доставляет это письмо, и есть убийца. Если хочешь, я могу доставить тебе её голову, когда караван закончит свой обход по Степям. Я знаю, ты любишь такие вещи для своей вуду-магии. Береги себя, старый друг. -Дарсок Быстрый Кинжал', 0),
(423, 'ruRU', 'Письма Торговой компании снаружи шахты... думаю, на каких-то ящиках на нижнем уровне. Удачи, и помни... Синий заряд: лесопилка Красный заряд: шахта Ах да, уничтожь это письмо после выполнения задания. Хм, может, мне стоит придумать способ, чтобы эти штуки сами себя уничтожали после прочтения. Это неплохая идея...', 0),
(466, 'ruRU', 'Чёрный дракон прошёл полное превращение; и в итоге Нелтарион перестал существовать. Он стал Смертокрылом, существом злобы и ненависти. Больше не Хранитель Земли в глазах таких рас, как высшие эльфы, он был переименован в Аспекта Смерти и Ксаксаса вместо данного титанами имени. Смертокрыл — воплощение хаоса и зла, вечно жаждущее разрушения. Он, пожалуй, первое зло Азерота, появившееся после изгнания Древних богов.', 0),
(506, 'ruRU', 'ПОЗДРАВЛЯЕМ! Вы — гордый новый владелец удивительного фыркающего сурка! Хотя это застенчивое создание, мы уверены, что вы найдёте пушистую миловидность и невероятные обонятельные способности своего нового питомца очаровательными. На следующих страницах вы найдёте информацию о вашем сурке: 1. Кормление и уход 2. Эксцентричное (и очаровательное) поведение 3. Использование патентованной Командной палочки Фыркунчика(тм) Ещё раз поздравляем. Вы не будете разочарованы, -Марвиг Растболт Владелец, Snuff Inc.', 0),
(571, 'ruRU', '--День 16 Улег и Таргил вернулись со своей миссии в доки Тераморта. Они увидели новый корабль в порту: «Кровоточащий воробей». Корабль прибыл из гавани Менетил в Азероте. Завтра Улег и Таргил вернутся в доки и прокрадутся на борт корабля. Они надеются найти политические документы, раскрывающие отношения между Тераморт и Альянсом.', 0),
(606, 'ruRU', 'Ожидай, что атака произойдёт в нескольких милях от их цели. Именно там будут поджидать наши??? союзники???. Не уверен, почему нас заставили заключить союз с этими существами, но не могу не чувствовать, что нас самих принуждают. В конечном счёте, это не будет иметь значения. Заполучив цель под стражу, мы будем на пути к возвращению Штормграда от тех, кто украл его у нас!', 0),
(626, 'ruRU', 'Мастер Длиннобород, как вы знаете, мы, Штормпики, ценим превосходное качество, и качество ваших щитов для нас не секрет. Поэтому я хотел бы заказать вам такой щит. Я приложил спецификации на следующей странице:', 0),
(689, 'ruRU', 'Оплата будет произведена по обычным каналам. И дайте подателю этой просьбы стандартную доплату за доставку. Можете добавить её к стоимости щита. С уважением и большой благодарностью, --Грингер Штормпик', 0),
(695, 'ruRU', 'Слово ПРЕДАТЕЛЬ грубо выцарапано над искусно выгравированной эпитафией, которая гласит: Здесь лежит Юрив. Отец, муж, паладин. Пусть его дети будут свидетелями того, что его преданность Свету была непоколебимой. Он никогда не попросил бы их сделать то, чего не сделал бы сам.', 0),
(730, 'ruRU', 'Хелгрум, мои комплименты тому, кто отдал приказ основать нашу базу Каргат в Суровых землях. Это идеальное место для тренировки наших войск. Суровая погода, свирепая живность, воинственные туземцы и полное отсутствие внешней поддержки делают это место тем горном, из которого выйдут только лучшие воины и разведчики. Хорошее планирование. Отлично сделано.', 0),
(750, 'ruRU', '<HTML>\n<BODY>\n<BR/>\n<BR/>\n<H1 align="center">\nЭлиза\n</H1>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align="center">\nЛюбимая жена, пусть земля утолит твой голод.\n</P>\n</BODY>\n</HTML>\n', 0),
(770, 'ruRU', 'Эй, мон. Отнеси эту грамотку Франгу в Долину Испытаний. Он обычно стоит возле Логова, гоняя молодых воинов, чтобы те были готовы сражаться за Орду.$B$BЕму нужны хитрые воины вроде тебя, чтобы показать оркам, как сражаться чем-то кроме мускулов. Ты быстрее и умнее большинства, но не хвастайся этим — орки не любят оскорблений. Они хорошие союзники, и может, они и тебя кое-чему научат.$B$B-Тар''сере', 0),
(790, 'ruRU', 'КОРМЛЕНИЕ И УХОД: Мы обязуемся предоставить вам всё необходимое для заботы о вашем питомце. Наши клиенты привыкли ожидать такого уровня сервиса от Snuff Inc, и мы с этим согласны! Для этого мы разработали прочные клетки для сурков с маленькими отверстиями, идеально подходящие для безопасного, надёжного содержания вашего питомца без доступа света. Для вашего удобства внутри каждой клетки есть отсек для пищевых гранул, пропитанных манящим ароматом синелистных тубероидов (любимое лакомство фыркающего сурка)!', 0),
(810, 'ruRU', 'Аку''май, принцесса глубин, служит Древним богам. Она обитает в Непроглядной Пучине, благословляя её пещеры своей древней мудростью. Приведённая в Пучину более древними смертными, Аку''май — символ божественности. У неё лишь крупица силы и свирепости Древних богов, и всё же её могущество неизмеримо. И потому её почитают. И её боятся, и любят. --Лорголис', 0),
(830, 'ruRU', 'Грязных троггов так легко обмануть. Их ненависть к нашему роду делает их управление и использование как пешек намного проще. Удивительно, что вообще можно было создать какой-то союз, но наш род представляет для них гораздо большую угрозу... по крайней мере пока. Но после начала атак обе стороны будут слабы и уязвимы для нашего собственного натиска. Займите усадьбу южнее озера Хелмс-Бед и ждите дальнейших указаний. Стальгорн будет нашим.', 0),
(832, 'ruRU', 'Обожжённые клыки паука:$B$BРуда инсендицита, найденная в пещере близ Скалы Телгена, обожгла пауков, обитающих там.$B$BЯд в их клыках кипит и реагирует с самими клыками, образуя очень прочное вещество.', 0),
(833, 'ruRU', 'Обугленные рога:$B$BПодобно обожжённым клыкам паука, обугленные рога химер, обитающих в Обугленной долине, в горах Каменного Когтя на Калимдоре, обладают очень ценным качеством.$B$BПроплавленные и правильно обработанные, они становятся крайне устойчивыми к физическому воздействию.', 0),
(834, 'ruRU', 'Гальванизированный рог:$B$BПрочность редкого гальванизированного рога — ключевой элемент всего доспеха, который я создам, так что его тоже нужно добыть.$B$BЕго можно получить от редкой матриарх-химеры в Обугленной долине.', 0),
(835, 'ruRU', 'Флакон флогистона:$B$BПоследний этап создания доспеха требует крайне горячей кузни. Чтобы достичь нужного уровня жара, мне нужен флакон флогистона.$B$BЕдинственный известный его создатель — легендарный свинобраз Руггуг, и он не отдаст его без боя. Руггуг обитает глубоко в Колючем Поле в южных Степях.', 0),
(850, 'ruRU', 'На следующих страницах вы найдёте список материалов, необходимых для изготовления огнестойкого доспеха. Удачи, воин. -Фурен Длиннобород', 0),
(870, 'ruRU', 'Эссенция изгнанника: Эта эссенция получается через слияние трёх талисманов элементалей-изгнанников Аратийских гор. Собери Громовые, Горящие и Венчающие талисманы у элементалей, затем помести по восемь каждого в мой котёл. Из талисманов сформируется эссенция изгнанника.', 0),
(877, 'ruRU', 'Кор-самоцвет — Судя по рассказам, что мне поведали, эти самоцветы используются некоторыми заклинателями для накопления энергии в своей магии, делая её ещё смертоноснее. Ночной эльф, которому я однажды помог, Тундрис Ветроткач, может рассказать тебе больше, поскольку ты будешь говорить от моего имени. Я полагаю, что накопленную энергию одного из самоцветов можно использовать при создании твоего оружия.$B$BКогда мы говорили в последний раз, Тундрис был в Аубердине, городке в глубине Тёмного Берега, порченого леса, протянувшегося вдоль побережья в тени родины ночных эльфов.', 0),
(890, 'ruRU', 'Кор-самоцвет — Судя по рассказам, что мне поведали, эти самоцветы используются некоторыми заклинателями для накопления энергии в своей магии, делая её ещё смертоноснее. Ночной эльф, которому я однажды помог, Тундрис Ветроткач, может рассказать тебе больше, поскольку ты будешь говорить от моего имени. Я полагаю, что накопленную энергию одного из самоцветов можно использовать при создании твоего оружия. Когда мы говорили в последний раз, Тундрис был в Аубердине, городке в глубине Тёмного Берега, порченого леса, протянувшегося вдоль побережья в тени родины ночных эльфов.', 0),
(910, 'ruRU', 'Вихрящиеся символы и пиктограммы, заполняющие страницы этого руководства, непостижимо эзотеричны.', 0),
(912, 'ruRU', 'Добудь Заряженную Молнией Колючку. Чтобы получить такую, собери 10 Палок Тотема Иссохшей Коры у троллей Иссохшей Коры в Высокогорьях Арати. Принеси палки к Кругу Внешнего Связывания, кольцу камней в тех же высокогорьях. Положи палки на центральный камень в круге и жди, когда в него ударит молния. Когда это случится, сформируется Заряженная Молнией Колючка.', 12340),
(930, 'ruRU', 'Добудь нефрит. Он прячется в самых разных местах. Он редок, но если поговорить с кузнецом или инженером, у них может найтись один-два в запасе.', 0),
(950, 'ruRU', '$N, ниже перечислены предметы, необходимые для создания твоего доспеха: Дымчатые железные слитки от кобольдов Буревея в шахте Буревея в горах Каменного Когтя. Порошковый азурит от хиллсбрадских шахтёров в Хиллсбраде. Железные слитки от шахтёров или из железных месторождений, если ты сам шахтёр. Флакон флогистона от свинобраза по имени Руггуг в Колючем Поле.', 0),
(953, 'ruRU', 'Песнь об Амет''Аране\n\nДолго дети звёзд жили на берегах мерцающих вод вечного колодца. Всем было известно, что Элуна, Свет вечных сумерек, Аспект и Богиня Луны, обитала в его водах, когда отдыхала от своих трудов. На берегах колодца дети звёзд, любимцы Элуны, строили свои дома. Даже когда их взгляд был устремлён вечно в небо, в залитую лунным светом ночь.', 0),
(954, 'ruRU', 'Падение Амет''Арана\n\nЗемля содрогнулась, когда древние деревья заколдованного леса были вырваны с корнем и повержены. Рощи и поляны, за которыми ухаживали сыновья и дочери Кенария, и каменные башни Детей Звёзд были сровнены с холмистой землёй. Там была наша Королева, лучезарная даже в отчаянии, в хаосе, которым стали битвы. Заколдованное небо меняло цвета от выброса магии, от взрывов, грозивших разорвать мир на части.', 0),
(970, 'ruRU', '(Только отдельные части дневника можно разобрать из-за пятен.) Ульдаман, День 3 Не могу поверить, как глупо я поступил. Быть захваченным врасплох мерзкими дворфами Тенегорна — ошибка новичка. Мои раны заживают медленно; должно быть, я отравлен. Я чувствую, как силы покидают меня. Тем не менее, я должен разведать путь дальше... ...в довершение всего, ожерелье, которое сделал мне гном, разбито! Три самых крупных камня, вставленных в него, потеряны. Я должен найти их; без них ожерелье бессильно...', 0),
(990, 'ruRU', 'Ульдаман, День 7 ...последний шанс на искупление моих неудач. Я верю, что рубин находится в последней забаррикадированной зоне, которую дворфы удерживают от троггов. Их битвы, несомненно, из-за камней и других артефактов этого места, не прекращаются. Это было бы так похоже на этих мерзких дворфов — спрятать его где-то там. В любом случае, я должен что-то предпринять. Возможно, безумный рывок к поверхности — лучший выход...', 0),
(1010, 'ruRU', 'Податель этого сертификата имеет право на уважение и почёт, которого заслуживает первоклассный воришка и вор.', 0);
